<summary>Harness source — reproducible; save as <code>proof-codex-projector.ts</code> at the repo root and run <code>npx tsx proof-codex-projector.ts</code></summary>

```ts
// Standalone projector harness — NOT a vitest test.
//
// Drives the REAL CodexAppServerEventProjector (no mocks, no assertion
// framework) against crafted Codex app-server notifications and prints a
// terminal transcript of the projected behavior, including the real
// embeddedAgentLog.warn diagnostics the shipped projector emits.
//
// Run:  npx tsx proof-codex-projector.ts
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
import { SessionManager } from "openclaw/plugin-sdk/agent-sessions";
import { CodexAppServerEventProjector } from "./extensions/codex/src/app-server/event-projector.js";

const THREAD_ID = "thread-proof";
const TURN_ID = "turn-proof";

type AnyRecord = Record<string, unknown>;
const agentEvents: AnyRecord[] = [];

// Real-logger tap: keep embeddedAgentLog.warn's real behavior, AND mirror each
// warning to stdout so the transcript is visible. This is the same logger
// instance the shipped projector writes through (imported via the same alias),
// so the tap observes genuine runtime diagnostics rather than a mocked spy.
const realWarn = embeddedAgentLog.warn.bind(embeddedAgentLog);
const warnings: { message: string; payload: unknown }[] = [];
embeddedAgentLog.warn = ((message: string, payload?: unknown) => {
  warnings.push({ message, payload });
  console.log(`  [warn] ${message} ${JSON.stringify(payload)}`);
  try {
    realWarn(message, payload);
  } catch {
    /* swallow — runtime logger side-effects are not the point of this tap */
  }
}) as typeof embeddedAgentLog.warn;

function codexModel() {
  return {
    id: "gpt-5.4-codex",
    name: "gpt-5.4-codex",
    provider: "openai",
    api: "openai-chatgpt-responses",
    input: ["text"],
    reasoning: true,
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 128_000,
    maxTokens: 8_000,
  };
}

function commandItem(id: string, command: string, status: string, extra: AnyRecord = {}) {
  return {
    type: "commandExecution",
    id,
    command,
    cwd: "/workspace",
    processId: null,
    source: "agent",
    status,
    commandActions: [],
    aggregatedOutput: extra.aggregatedOutput ?? null,
    exitCode: extra.exitCode ?? null,
    durationMs: extra.durationMs ?? null,
  };
}

function findToolResult(itemId: string): AnyRecord | undefined {
  for (const event of agentEvents) {
    const data = event.data as AnyRecord | undefined;
    if (
      event.stream === "tool" &&
      data?.phase === "result" &&
      data?.itemId === itemId
    ) {
      return data;
    }
  }
  return undefined;
}

async function main() {
  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "proof-codex-"));
  const sessionFile = path.join(tempDir, "session.jsonl");
  SessionManager.open(sessionFile).appendMessage({
    role: "assistant",
    content: [{ type: "text", text: "history" }],
    api: "openai-chatgpt-responses",
    provider: "openai",
    model: "gpt-5.4-codex",
    usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } },
    stopReason: "stop",
    timestamp: 1_750_000_000_000,
  } as AnyRecord);

  const projector = new CodexAppServerEventProjector(
    {
      prompt: "hello",
      sessionId: "session-proof",
      sessionFile,
      workspaceDir: tempDir,
      runId: "run-proof",
      provider: "openai",
      modelId: "gpt-5.4-codex",
      model: codexModel(),
      thinkLevel: "medium",
      onAgentEvent: (event: AnyRecord) => agentEvents.push(event),
    } as AnyRecord,
    THREAD_ID,
    TURN_ID,
  );

  const forCurrentTurn = (method: string, params: AnyRecord) => ({
    method,
    params: { threadId: THREAD_ID, turnId: TURN_ID, ...params },
  });

  console.log("=== CodexAppServerEventProjector standalone harness ===");
  console.log("(real projector class + real embeddedAgentLog; no vitest, no assertions)\n");

  console.log("--- Scenario 1: item/completed with UNRECOGNIZED status 'pausedByProtocol' (fail-closed) ---");
  await projector.handleNotification(
    forCurrentTurn("item/started", { startedAtMs: 1_750_000_000_000,
      item: commandItem("cmd-unknown", "echo unknown", "inProgress") }) as AnyRecord,
  );
  await projector.handleNotification(
    forCurrentTurn("item/completed", { completedAtMs: 1_750_000_000_042,
      item: commandItem("cmd-unknown", "echo unknown", "pausedByProtocol",
        { aggregatedOutput: "ok", exitCode: 0, durationMs: 42 }) }) as AnyRecord,
  );
  const unknownStatusResult = findToolResult("cmd-unknown");
  console.log(
    `  projected tool result -> status=${unknownStatusResult?.status} isError=${unknownStatusResult?.isError}  (fail-closed on unknown status)\n`,
  );

  console.log("--- Scenario 2: unhandled method 'item/futureStatus/updated' for the ACTIVE turn (warn-once) ---");
  for (let i = 0; i < 2; i += 1) {
    await projector.handleNotification(
      forCurrentTurn("item/futureStatus/updated", { itemId: "msg-1" }) as AnyRecord,
    );
  }
  console.log(`  fed twice; method-not-handled warnings for this method = ${
    warnings.filter((w) => w.payload && (w.payload as AnyRecord).method === "item/futureStatus/updated"
      && w.message.includes("not handled by projector")).length
  } (deduped to 1)\n`);

  console.log("--- Scenario 3: thread-scoped method 'thread/status/changed' — same thread, NO turnId (P3 fix) ---");
  for (let i = 0; i < 2; i += 1) {
    await projector.handleNotification({
      method: "thread/status/changed",
      params: { threadId: THREAD_ID, status: "active" },
    } as AnyRecord);
  }
  const driftForThreadScoped = warnings.filter(
    (w) => w.message.includes("did not match active thread/turn") &&
      (w.payload as AnyRecord)?.method === "thread/status/changed",
  ).length;
  console.log(
    `  reaches unknown-method path (breadcrumb emitted); mislabeled-as-drift warnings = ${driftForThreadScoped} (expected 0)\n`,
  );

  console.log("--- Scenario 4: item/completed for a DIFFERENT turn 'turn-other' (genuine correlation drift, warn-once) ---");
  for (let i = 0; i < 2; i += 1) {
    await projector.handleNotification({
      method: "item/completed",
      params: {
        threadId: THREAD_ID,
        turnId: "turn-other",
        completedAtMs: 1_750_000_000_042,
        item: commandItem("cmd-mismatch", "echo mismatch", "completed",
          { aggregatedOutput: "ok", exitCode: 0, durationMs: 42 }),
      },
    } as AnyRecord);
  }
  console.log(`  fed twice; drift warnings for 'item/completed' = ${
    warnings.filter((w) => w.message.includes("did not match active thread/turn") &&
      (w.payload as AnyRecord)?.method === "item/completed").length
  } (deduped to 1)\n`);

  console.log("--- Summary ---");
  console.log(`  total embeddedAgentLog.warn diagnostics emitted: ${warnings.length}`);
  console.log(`  distinct warning messages: ${
    [...new Set(warnings.map((w) => w.message))].join(" | ")
  }`);

  await fs.rm(tempDir, { recursive: true, force: true });
}

main().catch((error) => {
  console.error("harness failed:", error);
  process.exit(1);
});
```

</details>
